import{_ as t,a,o,a4 as s}from"./chunks/framework.-FZumj2l.js";const p=JSON.parse('{"title":"Reviews","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/admin/customers/reviews/index.md","filePath":"api/rest-api/admin/customers/reviews/index.md","lastUpdated":1783079210000}'),r={name:"api/rest-api/admin/customers/reviews/index.md"};function i(d,e,n,c,l,h){return o(),a("div",null,e[0]||(e[0]=[s('<h1 id="reviews" tabindex="-1">Reviews <a class="header-anchor" href="#reviews" aria-label="Permalink to &quot;Reviews&quot;">​</a></h1><p>The Reviews menu is the moderation queue for the product reviews customers leave on the storefront. Reviews are written by shoppers against catalog products; this menu is <strong>moderation only</strong> — you approve, disapprove, or delete them, but you never author one here. It mirrors the admin <strong>Customers → Reviews</strong> screen.</p><h2 id="where-reviews-come-from" tabindex="-1">Where reviews come from <a class="header-anchor" href="#where-reviews-come-from" aria-label="Permalink to &quot;Where reviews come from&quot;">​</a></h2><p>Every row originates from a storefront customer submitting a review on a product. A review carries the shopper&#39;s rating, title, and comment, and may include attached images. New reviews land in <code>pending</code> until an admin acts on them.</p><h2 id="status-workflow" tabindex="-1">Status workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status workflow&quot;">​</a></h2><p>A review&#39;s <code>status</code> moves between three values:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>pending</code></td><td>Newly submitted, awaiting moderation. Not shown on the storefront yet.</td></tr><tr><td><code>approved</code></td><td>Visible on the product&#39;s storefront page.</td></tr><tr><td><code>disapproved</code></td><td>Hidden — rejected by a moderator.</td></tr></tbody></table><p>The only editable field is <code>status</code> — the rating, title, comment, and images belong to the customer and are not changed here. Approving a review can trigger a notification to its author.</p><h2 id="what-the-detail-response-exposes" tabindex="-1">What the detail response exposes <a class="header-anchor" href="#what-the-detail-response-exposes" aria-label="Permalink to &quot;What the detail response exposes&quot;">​</a></h2><p>The single-review <code>GET</code> embeds the related records so you don&#39;t need follow-up calls:</p><ul><li><code>product</code> — the reviewed product as a nested object.</li><li><code>customer</code> — the review&#39;s author as a nested object (may be absent for guest reviews).</li><li><code>images</code> — the attached review images as an array. <strong>Detail-only</strong> — listing rows omit images.</li></ul><h2 id="bulk-actions" tabindex="-1">Bulk actions <a class="header-anchor" href="#bulk-actions" aria-label="Permalink to &quot;Bulk actions&quot;">​</a></h2><ul><li><strong>Mass Delete</strong> removes several reviews at once.</li><li><strong>Mass Update Status</strong> sets the same status on several reviews in one call (<code>value</code> is <code>pending</code> / <code>approved</code> / <code>disapproved</code>).</li></ul><h2 id="endpoints-in-this-menu" tabindex="-1">Endpoints in this menu <a class="header-anchor" href="#endpoints-in-this-menu" aria-label="Permalink to &quot;Endpoints in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="./list.html">List Reviews</a></td><td><code>GET /api/admin/customers/reviews</code></td></tr><tr><td><a href="./detail.html">Review Detail</a></td><td><code>GET /api/admin/customers/reviews/{id}</code></td></tr><tr><td><a href="./update.html">Update Status</a></td><td><code>PUT /api/admin/customers/reviews/{id}</code></td></tr><tr><td><a href="./delete.html">Delete Review</a></td><td><code>DELETE /api/admin/customers/reviews/{id}</code></td></tr><tr><td><a href="./mass-delete.html">Mass Delete</a></td><td><code>POST /api/admin/customers/reviews/mass-delete</code></td></tr><tr><td><a href="./mass-update-status.html">Mass Update Status</a></td><td><code>POST /api/admin/customers/reviews/mass-update-status</code></td></tr></tbody></table><p>Permissions: <code>customers.reviews.edit</code> / <code>.delete</code>.</p><p>All endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',17)]))}const u=t(r,[["render",i]]);export{p as __pageData,u as default};
